#!/bin/bash
# Uninstall script for Spline
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Spline..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Spline if running..."
pkill -f "Spline" 2>/dev/null || true

# Unload service com.design.spline.ShipIt
echo "Unloading service com.design.spline.ShipIt..."
launchctl unload -w /Library/LaunchAgents/com.design.spline.ShipIt.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.design.spline.ShipIt.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.design.spline.ShipIt.plist 2>/dev/null || true

# Remove /Applications/Spline.app
echo "Removing /Applications/Spline.app..."
if [ -d "/Applications/Spline.app" ]; then
    rm -rf "/Applications/Spline.app" 2>/dev/null || true
elif [ -f "/Applications/Spline.app" ]; then
    rm -f "/Applications/Spline.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.design.spline.sfl*
echo "Removing $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.design.spline.sfl*..."
if [ -d "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.design.spline.sfl*" ]; then
    rm -rf "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.design.spline.sfl*" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.design.spline.sfl*" ]; then
    rm -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.design.spline.sfl*" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Spline
echo "Removing $HOME/Library/Application Support/Spline..."
if [ -d "$HOME/Library/Application Support/Spline" ]; then
    rm -rf "$HOME/Library/Application Support/Spline" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Spline" ]; then
    rm -f "$HOME/Library/Application Support/Spline" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/Spline
echo "Removing $HOME/Library/Logs/Spline..."
if [ -d "$HOME/Library/Logs/Spline" ]; then
    rm -rf "$HOME/Library/Logs/Spline" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/Spline" ]; then
    rm -f "$HOME/Library/Logs/Spline" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.design.spline.plist
echo "Removing $HOME/Library/Preferences/com.design.spline.plist..."
if [ -d "$HOME/Library/Preferences/com.design.spline.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.design.spline.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.design.spline.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.design.spline.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
